-- ---------------------------------------------------------------------------------------
-- Identifier generators for seed rows written by migrations. Application code generates
-- its own ids (src/common/ids); these exist because a migration cannot call it.
CREATE OR REPLACE FUNCTION core.gen_uuid_v7() RETURNS uuid
  LANGUAGE plpgsql VOLATILE
AS $$
DECLARE
  ms bigint := floor(extract(epoch FROM clock_timestamp()) * 1000);
  bytes bytea := uuid_send(gen_random_uuid());
BEGIN
  bytes := overlay(bytes PLACING substring(int8send(ms) FROM 3 FOR 6) FROM 1 FOR 6);
  bytes := set_byte(bytes, 6, (get_byte(bytes, 6) & 15) | 112);
  bytes := set_byte(bytes, 8, (get_byte(bytes, 8) & 63) | 128);
  RETURN encode(bytes, 'hex')::uuid;
END
$$;
--> statement-breakpoint
-- `{prefix}_{ULID}`, the format of src/common/ids/ids.ts. The random part takes 5 bits from
-- each of 16 bytes of two v4 UUIDs, skipping the version and variant bytes.
CREATE OR REPLACE FUNCTION core.gen_public_id(prefix text) RETURNS text
  LANGUAGE plpgsql VOLATILE
AS $$
DECLARE
  alphabet constant text := '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  random_bytes constant integer[] := ARRAY[0, 1, 2, 3, 4, 5, 7, 9, 10, 11, 12, 13, 14, 15, 16, 17];
  ms bigint := floor(extract(epoch FROM clock_timestamp()) * 1000);
  bytes bytea := uuid_send(gen_random_uuid()) || uuid_send(gen_random_uuid());
  result text := '';
  position integer;
BEGIN
  FOR i IN 1..10 LOOP
    result := substr(alphabet, (ms % 32)::integer + 1, 1) || result;
    ms := ms / 32;
  END LOOP;
  FOREACH position IN ARRAY random_bytes LOOP
    result := result || substr(alphabet, (get_byte(bytes, position) % 32) + 1, 1);
  END LOOP;
  RETURN prefix || '_' || result;
END
$$;
--> statement-breakpoint
