-- ---------------------------------------------------------------------------------------
-- Accounts. Never deleted. Only `name` and `active` change after creation: anything else
-- would change the meaning of lines already posted to the account.
CREATE OR REPLACE FUNCTION core.check_account_insert() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.merchant_id IS NOT NULL
     AND split_part(NEW.code, ':', 3) IS DISTINCT FROM (SELECT ref FROM core.merchants WHERE id = NEW.merchant_id) THEN
    RAISE EXCEPTION 'merchant account % must be qualified by its merchant ref', NEW.code
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION core.check_account_update() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF (NEW.id, NEW.ref, NEW.environment, NEW.code, NEW.type, NEW.normal_balance, NEW.currency,
      NEW.merchant_id, NEW.provider, NEW.purpose, NEW.is_system, NEW.created_at)
     IS DISTINCT FROM
     (OLD.id, OLD.ref, OLD.environment, OLD.code, OLD.type, OLD.normal_balance, OLD.currency,
      OLD.merchant_id, OLD.provider, OLD.purpose, OLD.is_system, OLD.created_at) THEN
    RAISE EXCEPTION 'core.accounts: only name and active can change'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END
$$;
