-- Journal entry registry: global uniqueness the partitioned journal cannot hold itself.
-- Rows are written only by the journal_entries insert trigger (trigger depth 2).
CREATE OR REPLACE FUNCTION core.guard_journal_entry_keys() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF pg_trigger_depth() < 2 THEN
    RAISE EXCEPTION 'core.journal_entry_keys is written only by journal entry inserts'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  RETURN NEW;
END
$$;
