-- Journal partitions (spec 5.1): the current month and three ahead, plus a default
-- partition as a safety net. Phase 9 partition automation creates months ahead.
DO $$
BEGIN
  PERFORM core.create_monthly_partitions('journal_entries', (now() AT TIME ZONE 'UTC')::date, 4, true);
  PERFORM core.create_monthly_partitions('journal_lines', (now() AT TIME ZONE 'UTC')::date, 4, true);
END
$$;
