-- ---------------------------------------------------------------------------------------
-- Journal entries (spec 5.3, 6.6). Insert-time checks; the balance check is deferred.
CREATE OR REPLACE FUNCTION core.register_journal_entry() RETURNS trigger
  LANGUAGE plpgsql
AS $$
DECLARE
  original record;
BEGIN
  -- Entries cannot be back- or forward-dated, and lines can only join an entry created in
  -- their own transaction (see core.prepare_journal_line).
  IF NEW.created_at IS DISTINCT FROM now() OR NEW.posted_at IS DISTINCT FROM now() THEN
    RAISE EXCEPTION 'journal_entries.created_at and posted_at are set by the database'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.reverses_entry_id IS NOT NULL THEN
    SELECT e.environment, e.currency, e.merchant_id, e.transaction_id, e.reverses_entry_id
      INTO original
      FROM core.journal_entry_keys k
      JOIN core.journal_entries e ON e.id = k.entry_id AND e.created_at = k.entry_created_at
     WHERE k.entry_id = NEW.reverses_entry_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'reversed journal entry % does not exist', NEW.reverses_entry_id
        USING ERRCODE = 'foreign_key_violation';
    END IF;
    IF original.reverses_entry_id IS NOT NULL THEN
      RAISE EXCEPTION 'journal entry % is a reversal and cannot be reversed', NEW.reverses_entry_id
        USING ERRCODE = 'check_violation';
    END IF;
    IF (original.environment, original.currency, original.merchant_id, original.transaction_id)
       IS DISTINCT FROM (NEW.environment, NEW.currency, NEW.merchant_id, NEW.transaction_id) THEN
      RAISE EXCEPTION 'a reversal must keep the environment, currency, merchant and transaction of the entry it reverses'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  INSERT INTO core.journal_entry_keys
    (idempotency_key, entry_id, entry_ref, entry_created_at, request_fingerprint, reverses_entry_id)
  VALUES
    (NEW.idempotency_key, NEW.id, NEW.ref, NEW.created_at, NEW.request_fingerprint, NEW.reverses_entry_id);
  RETURN NEW;
END
$$;
--> statement-breakpoint
-- Each line: dated by the database, attached to an entry of this transaction, in the
-- entry's currency, on an active account of the same environment that accepts the
-- currency, and on a merchant account only if the entry belongs to that merchant.
CREATE OR REPLACE FUNCTION core.prepare_journal_line() RETURNS trigger
  LANGUAGE plpgsql
AS $$
DECLARE
  entry record;
  account record;
BEGIN
  IF NEW.created_at IS DISTINCT FROM now() THEN
    RAISE EXCEPTION 'journal_lines.created_at is set by the database'
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT environment, currency, merchant_id INTO entry
    FROM core.journal_entries WHERE id = NEW.entry_id AND created_at = NEW.created_at;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'journal lines must be inserted in the transaction that creates their entry'
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF NEW.currency IS DISTINCT FROM entry.currency THEN
    RAISE EXCEPTION 'journal line currency % differs from entry currency %', NEW.currency, entry.currency
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT environment, currency, merchant_id, active INTO account
    FROM core.accounts WHERE id = NEW.account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account % does not exist', NEW.account_id
      USING ERRCODE = 'foreign_key_violation';
  END IF;
  IF NOT account.active THEN
    RAISE EXCEPTION 'account % is inactive', NEW.account_id USING ERRCODE = 'check_violation';
  END IF;
  IF account.environment <> entry.environment THEN
    RAISE EXCEPTION 'account % belongs to the % environment, the entry to %', NEW.account_id, account.environment, entry.environment
      USING ERRCODE = 'check_violation';
  END IF;
  IF account.currency IS NOT NULL AND account.currency <> NEW.currency THEN
    RAISE EXCEPTION 'account % only holds %', NEW.account_id, account.currency
      USING ERRCODE = 'check_violation';
  END IF;
  IF account.merchant_id IS NOT NULL AND account.merchant_id IS DISTINCT FROM entry.merchant_id THEN
    RAISE EXCEPTION 'account % belongs to another merchant than the entry', NEW.account_id
      USING ERRCODE = 'check_violation';
  END IF;
  NEW.merchant_id := account.merchant_id;
  RETURN NEW;
END
$$;
--> statement-breakpoint
-- Balance agreement (spec 5.3 rule 6): every line is applied to account_balances by this
-- trigger, in the same transaction. Callers lock the balance rows first, in ascending
-- account id order (rule 8), so these updates never wait.
CREATE OR REPLACE FUNCTION core.apply_journal_line() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO core.account_balances AS b
    (account_id, currency, posted_debits_minor, posted_credits_minor, version, updated_at)
  VALUES (
    NEW.account_id,
    NEW.currency,
    CASE WHEN NEW.direction = 'debit' THEN NEW.amount_minor ELSE 0 END,
    CASE WHEN NEW.direction = 'credit' THEN NEW.amount_minor ELSE 0 END,
    1,
    now()
  )
  ON CONFLICT (account_id, currency) DO UPDATE SET
    posted_debits_minor = b.posted_debits_minor + EXCLUDED.posted_debits_minor,
    posted_credits_minor = b.posted_credits_minor + EXCLUDED.posted_credits_minor,
    version = b.version + 1,
    updated_at = now();
  RETURN NULL;
END
$$;
--> statement-breakpoint
-- Balanced entries, at least two lines, and exact mirroring for reversals (spec 5.3 rules
-- 1 and 4, 6.6), asserted at commit for every entry and every line inserted.
CREATE OR REPLACE FUNCTION core.check_journal_entry() RETURNS trigger
  LANGUAGE plpgsql
AS $$
DECLARE
  target_entry uuid;
  line_count bigint;
  debits numeric;
  credits numeric;
  reverses uuid;
  original_created timestamptz;
BEGIN
  IF TG_ARGV[0] = 'line' THEN
    target_entry := NEW.entry_id;
  ELSE
    target_entry := NEW.id;
  END IF;
  SELECT count(*),
         coalesce(sum(amount_minor) FILTER (WHERE direction = 'debit'), 0),
         coalesce(sum(amount_minor) FILTER (WHERE direction = 'credit'), 0)
    INTO line_count, debits, credits
    FROM core.journal_lines l
   WHERE l.entry_id = target_entry AND l.created_at = NEW.created_at;
  IF line_count < 2 THEN
    RAISE EXCEPTION 'journal entry % has % line(s); at least two are required', target_entry, line_count
      USING ERRCODE = 'check_violation';
  END IF;
  IF debits <> credits THEN
    RAISE EXCEPTION 'journal entry % is unbalanced: debits % <> credits %', target_entry, debits, credits
      USING ERRCODE = 'check_violation';
  END IF;
  SELECT e.reverses_entry_id INTO reverses
    FROM core.journal_entries e WHERE e.id = target_entry AND e.created_at = NEW.created_at;
  IF reverses IS NOT NULL THEN
    SELECT k.entry_created_at INTO original_created FROM core.journal_entry_keys k WHERE k.entry_id = reverses;
    IF EXISTS (
         (SELECT account_id, CASE direction WHEN 'debit' THEN 'credit' ELSE 'debit' END, amount_minor
            FROM core.journal_lines WHERE journal_lines.entry_id = reverses AND created_at = original_created)
         EXCEPT ALL
         (SELECT account_id, direction, amount_minor
            FROM core.journal_lines WHERE journal_lines.entry_id = target_entry AND created_at = NEW.created_at))
       OR EXISTS (
         (SELECT account_id, direction, amount_minor
            FROM core.journal_lines WHERE journal_lines.entry_id = target_entry AND created_at = NEW.created_at)
         EXCEPT ALL
         (SELECT account_id, CASE direction WHEN 'debit' THEN 'credit' ELSE 'debit' END, amount_minor
            FROM core.journal_lines WHERE journal_lines.entry_id = reverses AND created_at = original_created)) THEN
      RAISE EXCEPTION 'journal entry % does not exactly reverse entry %', target_entry, reverses
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NULL;
END
$$;
