-- ---------------------------------------------------------------------------------------
-- Account balances: written only by core.apply_journal_line (trigger depth 2). The one
-- direct write allowed is inserting an all-zero row, which the posting service does so it
-- can lock rows that do not exist yet.
CREATE OR REPLACE FUNCTION core.guard_account_balance() RETURNS trigger
  LANGUAGE plpgsql
AS $$
BEGIN
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' AND NEW.posted_debits_minor = 0 AND NEW.posted_credits_minor = 0 AND NEW.version = 0 THEN
    IF EXISTS (SELECT 1 FROM core.accounts a WHERE a.id = NEW.account_id AND a.currency IS NOT NULL AND a.currency <> NEW.currency) THEN
      RAISE EXCEPTION 'account % does not hold %', NEW.account_id, NEW.currency
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'core.account_balances changes only through journal lines'
    USING ERRCODE = 'insufficient_privilege';
END
$$;
--> statement-breakpoint
CREATE TRIGGER account_balances_guard BEFORE INSERT OR UPDATE ON core.account_balances FOR EACH ROW EXECUTE FUNCTION core.guard_account_balance();--> statement-breakpoint
