-- Foreign key checks lock the referenced row with SELECT ... FOR KEY SHARE, run with the
-- privileges of the referenced table's owner, and Postgres requires UPDATE on at least one
-- column for that lock. The append-only tables that foreign keys reference therefore keep
-- UPDATE on `created_at` only; their append-only triggers still refuse every UPDATE.
GRANT UPDATE (created_at) ON core.currencies, core.journal_entry_keys, core.journal_entries TO mulapay_core_rw;
